INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('window-max-sum', 8, NULL, 'def gen():
    _s = [1591492142]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    V = 1000000000
    K = 0
    MODE = 0
    N = 200000
    a = [r(-V, V) for _ in range(N)]
    if MODE == 1:
        a.sort()
    k = max(1, min(N, K if K > 0 else N // 2))
    return f"{N} {k}\n{'' ''.join(map(str, a))}\n"
', '99999941403485', 0);
